/* How Smart Are You? — Tiny DOM helpers used everywhere: $ (one element), $$ (all elements as an array), root (<html>).
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],root=document.documentElement;
