/* ---- js/core/util.js ---- */
/* How Smart Are You? — Small shared helpers: safe numbers, day/week keys, a string hash, HTML escaping, number and time formatting.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
const num=(x,d=0)=>Number.isFinite(+x)&&+x>=0?Math.floor(+x):d;
const dayKey=d=>d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate();
const weekKey=()=>{const d=new Date();d.setDate(d.getDate()-((d.getDay()+6)%7));return dayKey(d)};
const hashStr=t=>{let h=0;for(const c of t)h=(h*31+c.charCodeAt(0))>>>0;return h};
const esc2=t=>String(t).replace(/[&<>"']/g,c=>'&#'+c.charCodeAt(0)+';');
const fmt=n=>Math.round(n).toLocaleString(),dur=t=>t>=3600?`${Math.floor(t/3600)}h ${Math.floor(t%3600/60)}m`:`${Math.floor(t/60)}m ${t%60}s`;
