/* How Smart Are You? — Lifetime record for the profile (games, accuracy, time played, coins earned), computed from data the game already keeps.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
/* ---------- lifetime record ---------- */
const defLife=()=>({playS:0,seeded:0});
function sanLife(r,raw){const d=defLife();if(r&&typeof r==='object'&&r.seeded){d.playS=num(r.playS);d.seeded=1;return d}
 /* first time on v9: count the time already recorded by finished Classic and Survival runs and Riddle Mode */
 const H=raw&&Array.isArray(raw.history)?raw.history:[];d.playS=H.reduce((t,h)=>t+(h&&!h.legacy?Math.min(3*3600,num(h.d)):0),0)+Math.round(num(raw&&raw.riddle&&raw.riddle.time)/1000);d.seeded=1;return d}
function addPlay(sec){if(Number.isFinite(sec)&&sec>0)S.life.playS+=Math.min(3*3600,Math.round(sec))}
/** Everything the profile's player record needs, from data the game already keeps. */
