/* How Smart Are You? — Values the achievement list checks against (on top of economy.js achVals0) and the days-played record.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
/** Values for the v0.15 milestones (added to achVals()). */
function achX15(){const H=S.history,R=H.filter(h=>!h.legacy),CL=R.filter(h=>h.mode!=='survival'),cg=S.cg,q=R.reduce((t,h)=>t+h.k+h.w,0),k=R.reduce((t,h)=>t+h.k,0);
 return{clAcc90:CL.some(h=>h.k+h.w>=20&&h.k/(h.k+h.w)>=.9)?1:0,accLife:q>=500?Math.floor(k/q*100):0,svRuns:H.filter(h=>h.mode==='survival').length,
  hvaWins:cg.wins-cg.online.wins,rdRuns:S.riddle.runs,gamesAll:H.length+cg.games+S.riddle.runs,dcTotal:S.daily.total,dcBest:S.daily.best}}

/* ===== v0.14: stats for the new achievements, days played, unlock pop-ups ===== */
/** Extra values for achVals(). Classic-only values ignore Survival runs. */
function achX(){const H=S.history,CL=H.filter(h=>h.mode!=='survival'&&!h.legacy),SV=H.filter(h=>h.mode==='survival'),X=S.cg.x,Rd=S.riddle,mx=a=>Math.max(0,...a);
 const days=new Set(S.days);for(const h of H)days.add(dayKey(new Date(h.t)));
 return{clBest:mx(CL.map(h=>h.s)),clFlaw:mx(CL.filter(h=>h.w===0).map(h=>h.k)),clSt:mx(CL.map(h=>h.st)),clK:mx(CL.map(h=>h.k)),
  clSummit:CL.some(h=>h.tr&&h.tr[6]&&h.tr[6][1]>=10&&h.tr[6][1]/h.tr[6][0]>=.8)?1:0,svSt:mx(SV.map(h=>h.st)),
  hvaStreak:X.bestStreak,hvaKoHard:X.koHard,hvaElite:X.elite,hvaGod:X.god,cgWins8:X.wins8,cgPerf8:X.perf8,
  rdHardPure:Rd.hardPure,rdUltraFast:Rd.ultraFast,rdBossClean:Rd.bossClean,rdBossRun:Rd.bossRun,
  shopPct:Math.floor(ITEMS.filter(i=>owns(i.id)).length/ITEMS.length*100),achN:ACH.filter(a=>S.ach[a.id]).length,days:days.size,missions:S.counters.missions,
  clutch:S.flags.clutch,renaissance:Object.values(S.modeDays).some(m=>(m&15)===15)?1:0,grandslam:['score6000','sv180','cggen','rdboss5'].every(id=>S.ach[id])?1:0}}
/** Remember which days you played, and which modes on each day (for Daily Devotion and Renaissance Mind).
    bit: 1 Classic, 2 Survival, 4 Human vs AI, 8 Riddle Mode, 16 online. */
function markDay(bit){const k=dayKey(new Date());if(!S.days.includes(k)){S.days.push(k);if(S.days.length>800)S.days.shift()}
 S.modeDays[k]=(S.modeDays[k]||0)|bit;const ks=Object.keys(S.modeDays);if(ks.length>14)for(const o of ks.slice(0,ks.length-14))delete S.modeDays[o]}
