/* ---- js/ui/achievement-popups.js ---- */
/* How Smart Are You? — Achievement unlock pop-ups: one at a time, at most three queued.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
/* ----- unlock pop-ups: one at a time, at most 3 queued (then a "+N more" card) ----- */
const ACHQ={q:[],busy:false,more:0};
function achPop(a){if(ACHQ.q.length>=3){ACHQ.more++;return}ACHQ.q.push(a);if(!ACHQ.busy)achNext()}
function achNext(){const a=ACHQ.q.shift();if(!a){if(ACHQ.more){const n=ACHQ.more;ACHQ.more=0;achShow(null,n)}else ACHQ.busy=false;return}ACHQ.busy=true;achShow(a)}
function achShow(a,more){const T=a?ACH_T[a.tier]:ACH_T[3],d=document.createElement('div');d.className='achpop'+(a&&a.tier>=5?' pres':'');d.style.setProperty('--tc',T[1]);d.setAttribute('role','status');
 const items=a?ITEMS.filter(i=>i.req&&i.req.ach===a.id):[];
 d.innerHTML=a?`<span class="api">${a.i}</span><div><small>${a.h?'Secret achievement unlocked!':'Achievement unlocked'} · <b style="color:${T[1]}">${T[0]}</b></small><b>${esc2(a.n)}</b><small>${rw(a.r)}${items.length?' · 🎁 '+items.map(i=>esc2(i.name)).join(', '):''}</small></div>`
  :`<span class="api">🏅</span><div><b>+${more} more achievement${more===1?'':'s'}</b><small>See them all in Achievements.</small></div>`;
 document.body.appendChild(d);if(a&&a.tier>=4&&!calm()){const r=d.getBoundingClientRect();setTimeout(()=>burst(a.tier>=5?'fireworks':'stars',r.left+r.width/2,r.top+r.height),250)}
 setTimeout(()=>d.classList.add('out'),a?3600:2600);setTimeout(()=>{d.remove();achNext()},a?4000:3000)}
;
/* ---- js/systems/missions.js ---- */
/* How Smart Are You? — Daily and weekly missions: rolling a new set, progress after each run, claiming. The mission list is in data/missions.js.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
function rollMissions(){const M=S.missions;let ch=0;
 for(const[sc,n,key]of[['daily',3,dayKey(new Date())],['weekly',4,weekKey()]]){if(M[sc]&&M[sc].key===key&&Array.isArray(M[sc].list))continue;
  /* v0.15.1: never roll back to an earlier day or week (a device clock moved backwards would otherwise
     hand out a fresh set of missions to claim again) */
  if(M[sc]&&Array.isArray(M[sc].list)&&/^\d{4}-\d{1,2}-\d{1,2}$/.test(M[sc].key)&&dcIndex(key)<dcIndex(M[sc].key))continue;ch=1;
  let h=hashStr(sc+key);const idx=MPOOL[sc].map((_,i)=>i),pk=[];while(pk.length<n){pk.push(idx.splice(h%idx.length,1)[0]);h=Math.floor(h/7)+13}
  M[sc]={key,list:pk.map(i=>({i,p:0,s:[],c:0}))}}
 if(ch)persist()}
function missionProg(m,type,e,log){if(type==='correct')m.p+=e.k;else if(type==='runs')m.p+=1;else if(type==='streak')m.p=Math.max(m.p,e.st);else if(type==='score')m.p=Math.max(m.p,e.s);
 else if(type==='fast')m.p+=log.filter(x=>x.ok&&x.ms<=3000).length;else if(type==='surv'){if(e.mode==='survival')m.p=Math.max(m.p,Math.floor(e.sv/1000))}else if(type==='survk'){if(e.mode==='survival')m.p=Math.max(m.p,e.k)}else if(type==='cats'){for(const k in e.cats)if(e.cats[k][0]>0&&!m.s.includes(k))m.s.push(k);m.p=m.s.length}}
function afterRun(r){if(r.extra)return r.extra;const x=r.extra={ach:[],mis:[]};if(r.empty)return x;rollMissions();const e=S.history[S.history.length-1];
 for(const sc in S.missions)for(const m of S.missions[sc].list){const P=MPOOL[sc][m.i],was=m.p>=P[1];missionProg(m,P[0],e,G.log);if(!was&&m.p>=P[1])x.mis.push(P[2])}
 x.ach=checkAch();persist();return x}
function claimMission(sc,i){rollMissions();const m=S.missions[sc]&&S.missions[sc].list[i];if(!m||m.c)return false;if(m.p<MPOOL[sc][m.i][1])return false;m.c=1;S.counters.missions++;grant(...MREW[sc]);const un=checkAch();persist();return un.length?un:true}
;
/* ---- js/systems/statistics.js ---- */
/* How Smart Are You? — Statistics computed from recorded Classic and Survival runs.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
/* ===== Statistics: always computed from recorded games ===== */
function statsFor(range,mode){const lim={today:new Date().setHours(0,0,0,0),week:Date.now()-7*864e5,month:Date.now()-30*864e5,all:0}[range]||0;
 const H=S.history.filter(h=>h.t>=lim&&(!mode||mode==='all'||h.mode===mode)),R=H.filter(h=>!h.legacy),sum=(a,f)=>a.reduce((x,h)=>x+f(h),0);
 const q=sum(R,h=>h.k+h.w),c=sum(R,h=>h.k),n=sum(R,h=>h.n),fs=R.map(h=>h.f).filter(x=>x>0);
 return{H,R,games:H.length,q,c,w:q-c,acc:q?c/q*100:0,best:Math.max(0,...H.map(h=>h.s)),streak:Math.max(0,...R.map(h=>h.st)),xp:sum(R,h=>h.xp),coins:sum(R,h=>h.co),tier:Math.max(0,...H.map(h=>h.tier)),time:sum(R,h=>h.d),avg:n?sum(R,h=>h.rt)/n:0,fast:fs.length?Math.min(...fs):0}}
;
/* ---- js/systems/shop.js ---- */
/* How Smart Are You? — Shop rules: item state, buying (every check repeated so nothing is bought twice), equipping and today's featured items.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
/* ===== SHOP LOGIC: ownership, buying, equipping =====
   Everything re-checks the save each time, so a double click or a stale screen
   can never buy twice or spend currency without giving the item. */
const owns=id=>ownsIn(S,id),reqMet=q=>reqMetIn(S,q);
const equippedV=slot=>(ITEM[S.inv.equipped[slot]]||ITEM[DEFAULT_EQUIP[slot]]).v;
const isEquipped=it=>it.slot==='avatar'?S.profile.avatar===it.v:S.inv.equipped[it.slot]===it.id;
function reqText(q){if(!q)return'';if(q.lvl)return`Reach level ${q.lvl}`;if(q.missions)return`Claim ${q.missions} mission rewards (${Math.min(q.missions,S.counters.missions)}/${q.missions})`;
 if(q.ach){const a=ACH.find(x=>x.id===q.ach);return a?(a.h&&!S.ach[a.id]?'Unlock a secret achievement':`Achievement: ${a.n}`):'An achievement'}return''}
function itemState(id){const it=ITEM[id],own=owns(id),pc=it.c||0,pg=it.g||0;
 return{it,own,eq:own&&isEquipped(it),locked:!own&&!reqMet(it.req),earned:!pc&&!pg&&!!it.req,free:!pc&&!pg&&!it.req,pc,pg,shortC:Math.max(0,pc-S.wallet.coins),shortG:Math.max(0,pg-S.wallet.gems)}}
let buying=false;
/** Buy one item. Returns {ok:true} or {ok:false,error}. Nothing changes unless every check passes. */
function buyItem(id){if(buying)return{ok:false,error:'One moment…'};buying=true;
 try{const it=ITEM[id];if(!it)return{ok:false,error:'That item isn’t available.'};const st=itemState(id);
  if(st.own)return{ok:false,error:'You already own this.'};
  if(!st.pc&&!st.pg)return{ok:false,error:'This one is earned by playing, not bought.'};
  if(st.locked)return{ok:false,error:reqText(it.req)+' to unlock this first.'};
  if(st.shortC||st.shortG)return{ok:false,error:st.shortC?`You need ${fmt(st.shortC)} more Brain Coins.`:`You need ${fmt(st.shortG)} more Gems.`};
  S.wallet.coins-=st.pc;S.wallet.gems-=st.pg;S.inv.owned.push(id);S.counters.purchases++;S.counters.spentC+=st.pc;S.counters.spentG+=st.pg;
  persist();return{ok:true}}finally{buying=false}}
function equipItem(id){const it=ITEM[id];if(!it||!owns(id))return false;if(it.slot==='avatar')S.profile.avatar=it.v;else S.inv.equipped[it.slot]=id;persist();applyLook();renderHome();return true}
function unequipSlot(slot){if(slot==='avatar'){S.profile.avatar='🧠'}else if(DEFAULT_EQUIP[slot])S.inv.equipped[slot]=DEFAULT_EQUIP[slot];else return false;persist();applyLook();renderHome();return true}
function resetLook(){for(const s in DEFAULT_EQUIP)S.inv.equipped[s]=DEFAULT_EQUIP[s];S.profile.avatar='🧠';persist();applyLook();renderHome()}
/** Today's featured items: four purchasable items the player doesn't own yet, picked from the
    local date so the selection changes daily. Featuring never hides or removes anything. */
function featuredToday(){const pool=ITEMS.filter(i=>(i.c||i.g)&&!owns(i.id)),all=pool.length?pool:ITEMS.filter(i=>i.c||i.g);
 let h=hashStr('feat'+dayKey(new Date()));const p=all.slice(),out=[];while(out.length<4&&p.length){out.push(p.splice(h%p.length,1)[0]);h=Math.floor(h/5)+7}return out}
;
