function avatarHTML(v,frame){const k=String(v).startsWith('svg:')&&SVGAV[v.slice(4)],n=++AVN,inner=k?`<svg viewBox="0 0 64 64" aria-hidden="true">${SVGAV[v.slice(4)].replace(/id="([\w-]+)"/g,`id="$1-${n}"`).replace(/url\(#([\w-]+)\)/g,`url(#$1-${n})`)}</svg>`:esc2(v);
 const f=frame===undefined?equippedV('frame'):frame;return`<span class="ava${f&&f!=='none'?' fr-'+f:''}">${inner}</span>`}
