/* ---- js/ui/look.js ---- */
/* How Smart Are You? — Applying the equipped look (theme, background, hover style). PV is a temporary shop preview that is never saved.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
/* ===== APPLYING THE LOOK ===== */
let PV=null;/* an active preview: {it, prev} — temporary, never saved */
const look=slot=>PV&&PV.it.slot===slot?PV.it.v:equippedV(slot);
const calm=()=>cfg.calm||matchMedia('(prefers-reduced-motion:reduce)').matches;
function applyLook(){const sk=look('theme');
 if(sk==='classic'){delete root.dataset.skin;root.style.setProperty('--h',cfg.h);if(cfg.mode)root.dataset.theme=cfg.mode;else delete root.dataset.theme}
 else{root.dataset.skin=sk;root.style.removeProperty('--h');delete root.dataset.theme}
 const hv=look('fxHover');if(hv==='none')delete root.dataset.hover;else root.dataset.hover=hv;
 root.classList.toggle('rm',!!cfg.calm);
 const hc=$('#huerow');if(hc)hc.hidden=sk!=='classic';const tg=$('#tg');if(tg)tg.hidden=sk!=='classic';
 clearTimeout(applyLook.t);applyLook.t=setTimeout(()=>{colors();bgReset()},60)}
;
/* ---- js/ui/effects.js ---- */
/* How Smart Are You? — Visual effects: bursts, sparks, correct-answer, click, reward, tier, streak and score effects.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
/* ===== EFFECTS ===== */
/* FXH: when set, effects are drawn inside that element (the live shop previews) instead of the page */
let FXH=null;function fxT(f,ms){const h=FXH;return setTimeout(()=>{const o=FXH;FXH=h;try{f()}finally{FXH=o}},ms)}
function fxSpawn(cls,x,y,vars,txt,life=1300){const e=document.createElement('span');e.className='fxp '+cls;let st=`--x0:${x}px;--y0:${y}px;`;for(const k in vars)st+=`--${k}:${vars[k]};`;e.style.cssText=st+(vars.bg?`background:${vars.bg}`:'');if(txt)e.textContent=txt;(FXH||document.body).appendChild(e);setTimeout(()=>e.remove(),life);return e}
function pal(){const cs=getComputedStyle(root);return[cs.getPropertyValue('--a'),cs.getPropertyValue('--b'),cs.getPropertyValue('--c'),'#facc15','#22c55e']}
function burst(kind,x,y,n=1){if(calm()&&kind!=='sparks')return;const P=pal();
 if(kind==='sparks')sparks(x,y);
 else if(kind==='confetti'||kind==='coins')for(let i=0;i<(kind==='coins'?16:26)*n;i++){const a=-Math.PI/2+(Math.random()-.5)*2.2,v=80+Math.random()*160;fxSpawn('cf',x,y,{x1:x+Math.cos(a)*v+'px',y1:y+Math.sin(a)*v+160+Math.random()*80+'px',rot:Math.random()*720+'deg',bg:kind==='coins'?'radial-gradient(circle at 35% 35%,#fff7c2,#f5b400 60%,#a16207)':P[i%5]},'',1200).style.borderRadius=kind==='coins'?'50%':'2px'}
 else if(kind==='burst'||kind==='ripple')for(let i=0;i<(kind==='ripple'?1:3);i++)fxT(()=>fxSpawn(kind==='ripple'?'ripk':'rg',x,y,{sc:kind==='ripple'?5:4+i*2}),i*110);
 else if(kind==='emoji'||kind==='hearts')for(let i=0;i<8;i++)fxSpawn('fl',x+(Math.random()-.5)*70,y,{x1:x+(Math.random()-.5)*150+'px',y1:y-120-Math.random()*70+'px'},kind==='emoji'?'🧠':['❤️','💖','💜'][i%3]);
 else if(kind==='stars')for(let i=0;i<10;i++){const e=fxSpawn('fl',x,y,{x1:x+(Math.random()-.5)*220+'px',y1:y+(Math.random()-.5)*220+'px'},'✦');e.style.color=P[i%3];e.style.fontSize=12+Math.random()*16+'px'}
 else if(kind==='comet')for(let i=0;i<9;i++)fxSpawn('str',x,y,{rot:i*40+'deg',c:P[i%3]},'',800);
 else if(kind==='prism'){for(let i=0;i<3;i++)fxT(()=>{fxSpawn('rg',x,y,{sc:3+i*2.2}).style.borderColor=P[i%5]},i*90);for(let i=0;i<12;i++)fxSpawn('str',x,y,{rot:i*30+'deg',c:`hsl(${i*30} 95% 65%)`},'',750)}
 else if(kind==='fireworks')for(let k=0;k<3;k++)fxT(()=>{const fx=x+(k-1)*120,fy=y-60-k*30;for(let i=0;i<12;i++)fxSpawn('str',fx,fy,{rot:i*30+'deg',c:P[(i+k)%5]},'',800)},k*260)}
function fxCorrect(x,y,style){burst(style||equippedV('fxCorrect'),x,y)}
function fxClick(x,y){const k=look('fxClick');if(k==='none')return;if(k==='sparks')sparks(x,y);else burst(k==='stars'?'stars':k,x,y)}
function fxReward(x=innerWidth/2,y=innerHeight/2,style){const k=style||look('fxReward');
 if(k==='gift'&&!calm()){const g=document.createElement('div');g.className='gift';g.textContent='🎁';document.body.appendChild(g);setTimeout(()=>{g.remove();burst('confetti',innerWidth/2,innerHeight/2)},900)}
 else if(k==='coins')burst('coins',x,y);else if(k==='fireworks')burst('fireworks',x,y);else sparks(x,y);
 const sp=look('sfx')==='reward';[660,880,1175].forEach((f,i)=>setTimeout(()=>beep(f,sp?.35:.18,.035),i*110))}
function fxTier(t,style){const k=style||equippedV('fxTier');if(k==='none')return;
 if(k==='shock'&&!calm()){const s=document.createElement('div');s.className='shock';document.body.appendChild(s);setTimeout(()=>s.remove(),950)}
 const b=document.createElement('div');b.className='tierb';b.setAttribute('role','status');b.textContent=`Tier ${t}: ${TN[t-1]}`;document.body.appendChild(b);setTimeout(()=>b.remove(),1700)}
function fxStreak(n,w=$('#stw'),style){if(!w)return;const k=style||equippedV('fxStreak');w.className='stw'+(k!=='none'?' fx-'+k:'')+(n>=3?' hot':'');w.style.setProperty('--n',Math.min(n,12))}
function fxScore(from,to,gain,el=$('#sc'),wrap=$('#scw'),style){if(!el)return;const k=style||equippedV('fxScore');
 if(k==='plain'||calm()||gain<=0){el.textContent=to;return}
 if(k==='float'){el.textContent=to;const f=document.createElement('span');f.className='ptsf';f.textContent='+'+gain;wrap.appendChild(f);setTimeout(()=>f.remove(),1000);return}
 const t0=performance.now();(function st(){const p=Math.min(1,(performance.now()-t0)/600);el.textContent=Math.round(from+(to-from)*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(st)})()}
/* sparks */
function sparks(x,y){const cs=getComputedStyle(root),cols=[cs.getPropertyValue('--a'),cs.getPropertyValue('--b'),cs.getPropertyValue('--c')];
 for(let i=0;i<14;i++){const s=document.createElement('span'),a=Math.random()*6.28,d=40+Math.random()*90;s.className='spark';s.style.cssText=`left:${x}px;top:${y}px;background:${cols[i%3]};--dx:${Math.cos(a)*d}px;--dy:${Math.sin(a)*d}px`;(FXH||document.body).appendChild(s);setTimeout(()=>s.remove(),850)}}
addEventListener('pointerdown',e=>{if(!e.target.closest('button,.panel,.pvbar')){fxClick(e.clientX,e.clientY);beep(660,.1)}});
;
/* ---- js/audio/sound.js ---- */
/* How Smart Are You? — Sound: sound packs, the mixer (master volume, limiter, sound-effects bus) and beep(). Everything is generated live with the Web Audio API; there are no audio files.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
/* ===== SOUND PACKS: every pack is generated live by the Web Audio API (no audio files) ===== */
const SFXP={classic:{w:'triangle'},soft:{w:'sine',v:1.1,d:1.5,att:.012},retro:{w:'square',v:.9,d:.8,q:1},digital:{w:'square',v:.85,d:.6,oct:1},future:{w:'sawtooth',v:.9,lp:2200,sw:1},reward:{w:'triangle',d:1.6,bell:1},crystal:{w:'sine',v:1.2,d:1.1,oct:1}};
function tone(f,d,v,P,at=0){const t=ac.currentTime+at,o=ac.createOscillator(),g=ac.createGain();o.type=P.w;
 if(P.q)f=440*Math.pow(2,Math.round(12*Math.log2(f/440))/12);
 o.frequency.setValueAtTime(f*(P.sw?.75:1),t);if(P.sw)o.frequency.exponentialRampToValueAtTime(f*1.15,t+d);
 g.gain.setValueAtTime(P.att?0.0001:v,t);if(P.att)g.gain.linearRampToValueAtTime(v,t+P.att);g.gain.exponentialRampToValueAtTime(.0001,t+d);
 let node=o;if(P.lp){const fl=ac.createBiquadFilter();fl.type='lowpass';fl.frequency.value=P.lp;o.connect(fl);node=fl}
 node.connect(g);g.connect(mix().sfx);o.start(t);o.stop(t+d+.02)}
/** The original beep(), extended: the equipped sound pack shapes the tone and the volume
    slider scales it. With the Classic pack at full volume it sounds exactly as before. */
const mastered=()=>cfg.master==null?1:cfg.master;
/* ===== The mixer =====================================================================
   sound effects ─┐
                  ├─ master volume ─ limiter ─ speakers
   music ─ duck ──┘
   Sound effects get their own boosted channel (they were up to 12× quieter than the music,
   which is why right/wrong answer sounds were hard to hear), and important sounds briefly
   turn the music down. The limiter stops loud moments from distorting. */
const MIX={ctx:null},SFX_BUS=4;
function mix(){if(!ac){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw new Error('no Web Audio');ac=new AC()}if(MIX.ctx!==ac){const m=ac.createGain(),lim=ac.createDynamicsCompressor();lim.threshold.value=-6;lim.knee.value=6;lim.ratio.value=12;lim.attack.value=.003;lim.release.value=.2;
  m.connect(lim);lim.connect(ac.destination);const s=ac.createGain();s.gain.value=SFX_BUS;s.connect(m);const mu=ac.createGain();mu.connect(m);m.gain.value=mastered();Object.assign(MIX,{ctx:ac,master:m,sfx:s,mus:mu})}return MIX}
function duck(a=.5,ms=450){if(!MIX.mus||MIX.ctx!==ac)return;const g=MIX.mus.gain,t=ac.currentTime;g.cancelScheduledValues(t);g.setTargetAtTime(1-a,t,.02);g.setTargetAtTime(1,t+ms/1000,.15)}
function beep(f,d=.09,v=.04,pack){if(!cfg.sound||!(cfg.vol>0)||HSAY_PLATFORM.adPlaying||window.HSAY_PAUSED)return;try{mix();if(ac.state==='suspended')ac.resume();
 const P=SFXP[pack||look('sfx')]||SFXP.classic,vv=v*(P.v||1)*cfg.vol,dd=d*(P.d||1);tone(f,dd,vv,P);
 if(P.oct)tone(f*2,dd*.6,vv*.6,P,.045);if(P.bell){tone(f*1.5,dd*1.2,vv*.45,P,.01);tone(f*2.01,dd*.8,vv*.25,P,.02)}}catch(e){}}
let ac;
function previewSound(pack){[[523,.12,.03],[600,.09,.04],[880,.2,.04],[220,.3,.04]].forEach(([f,d,v],i)=>setTimeout(()=>beep(f,d,v,pack),i*260));
 [660,880,1175].forEach((f,i)=>setTimeout(()=>beep(f,.25,.035,pack),1100+i*110))}
;
/* ---- js/audio/music.js ---- */
/* How Smart Are You? — Music: every track is a small score played live by a step sequencer. Menu tracks, mode tracks, previews, end-of-game jingles and unlocking audio on the first tap.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
/* ===== MUSIC =====================================================================
   Original background music, composed for this game and generated live with the Web Audio
   API, so there are no audio files and nothing licensed from anyone else.
   - Off by default. It only starts after the player turns it on (a click), which satisfies
     browser autoplay rules.
   - Its own volume, separate from sound effects.
   - "Auto" picks a track for where you are: menus, Classic or Survival.
   - Fades out and stops scheduling notes while the tab is hidden; resumes when you return.
   ================================================================================= */
/* Each track is a small score: chords (prog), patterns for each instrument (16 steps a bar,
   'x' = play) and a few settings. Every mode has its own track with its own instruments:
   - lobby  Neon Lobby   (menus, unchanged)       - think   Quiz Show (Classic: bright, major, claps and a hook)
   - edge   Last Second  (Survival: pulsing bass, speeds up and adds an alarm as the clock runs down)
   - arena  Neural Arena (Human vs AI: four-on-the-floor, pumping synths, echoing arpeggios)
   - showtime Showtime   (Category Game online: swung game-show groove with brass stabs)
   - mystery Hidden Door (Riddle Mode: slow bells with echoes over a low drone)
   - boss   Final Riddle (boss riddles: heavy toms, dissonant drone)       - orbit (calm, menus only)
   Extra fields: swing, bassOct (octave-jumping bass), clap/tom/stab/bell patterns, mel (a 2-bar
   melody of chord-tone numbers, -1 = rest), echo (how much goes to the echo), pump (pad ducks on
   each beat), drone, tense (reacts to MUS.tension, set by the Survival clock). */
