 if(k==='riddle'||k==='boss'){const sy=[...(k==='boss'?'✦?✧✶?⁂':'?✦⁇?✧?')];
  return Array.from({length:12},(_,i)=>`<i class="fl" style="--x:${(i*83+7)%100}%;--d:${9+(i*37)%8}s;--dl:-${(i*1.9).toFixed(1)}s;--s:${(.7+((i*7)%6)/6).toFixed(2)}">${sy[i%sy.length]}</i>`).join('')+'<b class="fog"></b>'+(k==='boss'?'<b class="runes"></b>':'')}
