/* ===== MODE INTRODUCTION AND COUNTDOWN ============================================
   Starting a game: the mode's stage and music come in, a title screen plays for about 5
   seconds, then 3 · 2 · 1 · GO! (about 3 seconds). Only after GO does the game start: no
   question, no timer and no AI move exists before then. Used when a game starts, not between
   questions. The bar on the title screen shows the time to the countdown, not loading:
   nothing is loaded (every sound and picture is made in the browser).
   ================================================================================= */
const INTRO=(()=>{const d={intro:5000,step:800,go:700};
 return d})();
const INTRO_TXT={classic:['Classic','TEST YOUR KNOWLEDGE'],survival:['Survival','HOW LONG CAN YOU SURVIVE?'],hva:['Human vs AI','CHALLENGE THE INTELLIGENCE OF AI'],
 cgarena:['Category Game','THINK FAST. OUTLAST EVERYONE.'],riddle:['Riddle Mode','NOT EVERYTHING IS AS IT SEEMS.'],boss:['Boss Riddle','ONLY THE SHARPEST MINDS GET PAST']};
let MI=null;
