 miStop();const g=$('#game');if(!g)return go();const T=INTRO_TXT[k],ms=o.intro==null?INTRO.intro:Math.max(0,o.intro);
 const cur=MI={k,go,live:o.live||(()=>true),t:[]};g.classList.add('intro');
