 const name=[...T[0]].map((c,i)=>`<span style="--i:${i}">${c===' '?'&nbsp;':esc2(c)}</span>`).join('');
 d.innerHTML=`<div class="mi-p" aria-hidden="true">${Array.from({length:14},(_,i)=>`<i style="--x:${(i*37+11)%100}%;--y:${(i*53+7)%100}%;--d:${(2+(i%5)*.6).toFixed(1)}s;--dl:-${(i*.37).toFixed(2)}s"></i>`).join('')}</div>
 <div class="mi-in"><div class="mi-ic" aria-hidden="true">${ENVS[k].i}</div><h2 class="mi-name" aria-label="${esc2(T[0])}">${name}</h2><p class="mi-tag">${T[1]}</p>${o.sub?`<p class="mi-sub">${esc2(o.sub)}</p>`:''}
 ${ms>=600?`<div class="mi-bar" aria-hidden="true"><i style="animation-duration:${ms}ms"></i></div><p class="mi-note">Get ready…</p>${o.skip===false?'':'<button class="chip mi-skip" type="button">Skip intro ›</button>'}`:''}</div>`;
 g.appendChild(d);cur.el=d;
