/* ---- js/systems/questions.js ---- */
/* How Smart Are You? — Categories and the question bank (from data/categories.js and data/questions.js), plus the generated maths questions.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
/* ===== Play: categories, typed answers, shrinking timer, best results ===== */
const CATDEF=HSAY_DATA.categories,CATS={random:['🎲','Random']};CATDEF.forEach(c=>CATS[c.k]=[c.i,c.n,c.g]);
const TN=['Warm-up','Easy','Tricky','Hard','Niche','Ultra niche'];
/* question file format: '#key' starts a category; 'tier|question|answer/alternative/...|flags'; ';' starts a comment */
const BANK={};{let cur;HSAY_DATA.questions.trim().split('\n').forEach(l=>{l=l.trim();if(!l||l[0]===';')return;if(l[0]==='#'){cur=l.slice(1).trim();BANK[cur]=[];return}const p=l.split('|');if(cur&&p.length>=3)BANK[cur].push([+p[0],p[1],p[2].split('/').map(x=>x.trim()).filter(Boolean),(p[3]||'').trim()])})}
const nz=s=>String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/^(the|a|an)\s+/,'').replace(/[^a-z0-9]/g,'');
const ri=(a,b)=>a+Math.floor(Math.random()*(b-a+1));
function mathQ(t){let q,a,x,y;
 if(t===1){x=ri(2,20);y=ri(2,20);q=`What is ${x} + ${y}?`;a=x+y}
 else if(t===2){x=ri(3,12);y=ri(3,12);q=`What is ${x} × ${y}?`;a=x*y}
 else if(t===3){x=ri(11,25);y=ri(3,9);q=`What is ${x} × ${y}?`;a=x*y}
 else if(t===4){x=[10,15,20,25,30,35,40,45,60,75][ri(0,9)];y=ri(2,20)*20;q=`What is ${x}% of ${y}?`;a=x*y/100}
 else if(t===5){x=ri(3,20);y=ri(2,9);const c=ri(3,30);q=`Solve for x: ${y}x + ${c} = ${y*x+c}`;a=x}
 else{const k=ri(0,2);if(k===0){x=ri(12,35);y=ri(12,35);q=`What is ${x} × ${y}?`;a=x*y}else if(k===1){x=ri(11,16);q=`What is 2^${x}? (2 to the power of ${x})`;a=2**x}else{x=ri(13,40);q=`What is the square root of ${x*x}?`;a=x}}
 return [t,q,[String(a)]]}
;
/* ---- js/systems/answers.js ---- */
/* How Smart Are You? — Answer checking for typed answers: normalising, number words, typo tolerance and guard words.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
/* ===== ANSWER CHECKING ==========================================================
   How a typed answer is judged, in order:
   1. Normalise both sides: lower case, accents removed, "&" read as "and", apostrophes,
      hyphens, spaces and punctuation ignored, a leading "the/a/an" ignored, decimal points
      between digits kept (9.8 stays 9.8), number words read as numbers ("twenty six" = 26).
   2. Exact match against the answer or any listed alternative.
   3. Recognised variants (not for "strict" questions): a missing or extra plural/possessive
      "s" (Popeye = Popeyes, McDonald = McDonald's), "saint" = "st", and the surname alone for
      "Who…" questions whose answer is a full name (Shakespeare = William Shakespeare).
   4. Small typos (not for strict questions, numbers or answers under 5 letters): the first
      letter must match; for 5 letters only two swapped letters; 1 slip for 6–9 letters, 2 for 10+. A typo is NOT accepted if what you
      typed is itself a different answer from the question bank (Austria is never Australia),
      or if it is at least as close to another answer in the same category.
   Question format in the database: tier|question|answer/alternative/...|flags (flags: strict)
   ================================================================================= */
const NUMW={zero:0,one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10,eleven:11,twelve:12,thirteen:13,fourteen:14,fifteen:15,sixteen:16,seventeen:17,eighteen:18,nineteen:19,twenty:20,thirty:30,forty:40,fifty:50,sixty:60,seventy:70,eighty:80,ninety:90};
/** "twenty six" -> "26", "one hundred" -> "100", "eighty-eight" -> "88"; anything else unchanged. */
function wordsToNum(s){const w=s.trim().replace(/-/g,' ').split(/\s+/).filter(x=>x&&x!=='and');if(!w.length||!w.every(x=>x in NUMW||x==='hundred'||x==='thousand'))return s;
 let total=0,cur=0;for(const x of w){if(x==='hundred')cur=(cur||1)*100;else if(x==='thousand'){total+=(cur||1)*1000;cur=0}else cur+=NUMW[x]}return String(total+cur)}
function norm(s){let t=String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/ß/g,'ss').replace(/æ/g,'ae').replace(/ø/g,'o').replace(/ł/g,'l').replace(/&/g,' and ').trim();
 t=wordsToNum(t.replace(/[^a-z0-9 .'-]/g,' '));
 t=t.replace(/^(the|a|an)\s+/,'').replace(/\bsaint\b/g,'st');
 t=t.replace(/(\d)[ ,](?=\d{3}\b)/g,'$1');                  // 300,000 or 300 000 -> 300000
 return t.replace(/(\d)\.(\d)/g,'$1\u0001$2').replace(/[^a-z0-9\u0001]/g,'').replace(/\u0001/g,'.')}
/** Edit distance counting an adjacent swap as one slip (optimal string alignment). */
function editDist(a,b,max=3){const m=a.length,n=b.length;if(Math.abs(m-n)>max)return max+1;
 let p2=null,p=Array.from({length:n+1},(_,j)=>j);
 for(let i=1;i<=m;i++){const c=[i];let best=i;for(let j=1;j<=n;j++){const s=a[i-1]===b[j-1]?0:1;c[j]=Math.min(p[j]+1,c[j-1]+1,p[j-1]+s);
  if(p2&&i>1&&j>1&&a[i-1]===b[j-2]&&a[i-2]===b[j-1])c[j]=Math.min(c[j],p2[j-2]+1);best=Math.min(best,c[j])}if(best>max)return max+1;p2=p;p=c}return p[n]}
const dropS=x=>x.length>=5&&!/\d/.test(x)?x.replace(/s$/,''):x;
let KNOWN=null,CATANS={};
/* Real words that a typo must never be turned into: every country and every chemical element.
   (Cerium is not Cesium, Slovakia is not Slovenia.) Answers from the whole bank are added too. */
const GUARD_WORDS='afghanistan albania algeria andorra angola argentina armenia australia austria azerbaijan bahamas bahrain bangladesh barbados belarus belgium belize benin bhutan bolivia bosnia botswana brazil brunei bulgaria burundi cambodia cameroon canada chad chile china colombia comoros congo croatia cuba cyprus czechia denmark djibouti dominica ecuador egypt eritrea estonia eswatini ethiopia fiji finland france gabon gambia georgia germany ghana greece grenada guatemala guinea guyana haiti honduras hungary iceland india indonesia iran iraq ireland israel italy jamaica japan jordan kazakhstan kenya kiribati kosovo kuwait kyrgyzstan laos latvia lebanon lesotho liberia libya liechtenstein lithuania luxembourg madagascar malawi malaysia maldives mali malta mauritania mauritius mexico micronesia moldova monaco mongolia montenegro morocco mozambique myanmar namibia nauru nepal netherlands nicaragua niger nigeria norway oman pakistan palau panama paraguay peru philippines poland portugal qatar romania russia rwanda samoa senegal serbia seychelles singapore slovakia slovenia somalia spain sudan suriname sweden switzerland syria taiwan tajikistan tanzania thailand togo tonga tunisia turkey turkmenistan tuvalu uganda ukraine uruguay uzbekistan vanuatu venezuela vietnam yemen zambia zimbabwe austria australia england scotland wales britain '+
 'hydrogen helium lithium beryllium boron carbon nitrogen oxygen fluorine neon sodium magnesium aluminium aluminum silicon phosphorus sulfur sulphur chlorine argon potassium calcium scandium titanium vanadium chromium manganese iron cobalt nickel copper zinc gallium germanium arsenic selenium bromine krypton rubidium strontium yttrium zirconium niobium molybdenum technetium ruthenium rhodium palladium silver cadmium indium tin antimony tellurium iodine xenon caesium cesium barium lanthanum cerium praseodymium neodymium promethium samarium europium gadolinium terbium dysprosium holmium erbium thulium ytterbium lutetium hafnium tantalum tungsten rhenium osmium iridium platinum gold mercury thallium lead bismuth polonium astatine radon francium radium actinium thorium protactinium uranium neptunium plutonium';
/** Index every accepted answer in the bank (built once, on first use). */
function answerIndex(){if(KNOWN)return;KNOWN=new Set(GUARD_WORDS.split(' '));for(const k in BANK){const set=new Set();for(const q of BANK[k])for(const a of q[2]){const n=norm(a);KNOWN.add(n);set.add(n)}CATANS[k]=set}}
/** Judge a typed answer. Returns {ok, how:'exact'|'variant'|'typo', answer} or {ok:false}. */
function judge(q,input,cat){const v=norm(input);if(!v)return{ok:false,empty:true};
 const strict=q[3]==='strict',alts=q[2].map(norm),main=q[2][0];
 if(alts.includes(v))return{ok:true,how:'exact',answer:main};
 if(strict)return{ok:false};
 /* recognised variants */
 if(alts.some(a=>dropS(a)===dropS(v)))return{ok:true,how:'variant',answer:main};
 if(/^who\b/i.test(q[1])){for(const a of q[2]){const w=a.toLowerCase().replace(/[^a-z\s'-]/g,'').trim().split(/\s+/);if(w.length>=2){const last=norm(w[w.length-1]);if(last.length>=4&&last===v)return{ok:true,how:'variant',answer:main}}}}
 /* small typos */
 if(/\d/.test(v)||v.length<4)return{ok:false};
 answerIndex();if(KNOWN.has(v))return{ok:false};               // a real, different answer
 let best=null,bd=9;
 for(const a of alts){if(/\d/.test(a)||a.length<5||a[0]!==v[0])continue;const allow=a.length>=10?2:1,d=editDist(v,a,allow);if(a.length<6&&(v.length!==a.length||[...v].sort().join('')!==[...a].sort().join('')))continue;if(d<=allow&&d<bd){bd=d;best=a}}
 if(!best)return{ok:false};
 const others=[...(CATANS[cat]||[])].filter(x=>!alts.includes(x));
 if(others.some(o=>editDist(v,o,bd)<=bd))return{ok:false};    // too close to a different answer
 return{ok:true,how:'typo',answer:main}}
;
/* ---- js/core/save-transfer.js ---- */
/* How Smart Are You? — Export, import, reset and the "last backup" reminder.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
/* Saving a file works differently when the page is hosted as an artifact, so try the
   hosted save first and fall back to a normal browser download, then to copy-and-paste. */
async function exportSave(){const json=JSON.stringify(S,null,1),name='how-smart-are-you-save.json';
 try{const d=window.claude&&claude.use?await claude.use('downloads'):null;
  if(d){await d.save({filename:name,data:json});(markExport(),toast('Save file downloaded.'));return}}catch(e){if(e&&e.code==='not_granted'){toast('Download was declined.');return}}
 try{const b=new Blob([json],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);(markExport(),toast('Save file downloaded.'));return}catch(e){}
 try{await navigator.clipboard.writeText(json);(markExport(),toast('Save copied to the clipboard. Paste it into a text file to keep it.'))}
 catch(e){const w=$('#pg');if(w){const ta=document.createElement('textarea');ta.className='nm';ta.rows=6;ta.value=json;ta.readOnly=true;w.appendChild(ta);ta.select();toast('Copy the text below to back up your save.')}}}
function applySave(ns){Object.assign(cfg,ns.settings);ns.settings=cfg;S=ns;ALLOW_EMPTY_WRITE=true;try{persist()}finally{ALLOW_EMPTY_WRITE=false}if(!hasProgress(S))try{localStorage.removeItem(LASTGOOD_KEY)}catch(e){}else keepLastGood(true);sync();renderHome();musSync();musUI()}
function importText(txt){if(typeof txt!=='string'||txt.length>5e6){toast('That’s too big to be a save.');beep(220,.25);return false}/* same limit as an imported file */const r=parseImport(txt);if(r.error){toast(r.error);beep(220,.25);return false}applySave(r.save);checkAch();showPage('profile');toast(r.newer?'Save imported. It came from a newer version, so anything this version doesn’t know was left out.':'Save imported.');return true}
function markExport(){S.flags.exp=Date.now();persist()}
function backupLine(){const t=S.flags.exp,d=t?Math.floor((Date.now()-t)/864e5):-1;
 return`<p class="mut bkline">${t?`💾 Last backup: ${d<=0?'today':d===1?'yesterday':d+' days ago'}.`:'💾 No backup yet.'}${!t||d>=14?' Some browsers, Safari in particular, can clear saved data for sites you haven’t opened for a while, so an exported copy is the safe way to keep your progress.':''}</p>`}
;
