const M=(a,b)=>`<div class="m"><b>${a}</b><small>${b}</small></div>`;
function spark(v,f){if(v.length<2)return'<p class="mut">Play a couple more games to see this chart.</p>';const w=300,h=70,mx=Math.max(...v),mn=Math.min(...v,0),pts=v.map((x,i)=>`${(i/(v.length-1)*w).toFixed(1)},${(h-4-(x-mn)/((mx-mn)||1)*(h-8)).toFixed(1)}`).join(' ');
 return `<svg viewBox="0 0 ${w} ${h}" class="spark2" role="img" aria-label="Chart, latest ${f(v[v.length-1])}"><polyline points="${pts}" fill="none" stroke="var(--a)" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/></svg><div class="mut">Latest ${f(v[v.length-1])} · Best ${f(mx)}</div>`}
const PAGES={progress:'📈 Progress',stats:'📊 Stats',achievements:'🏅 Achievements',missions:'🎯 Missions',profile:'👤 Profile'};
