/* ---- js/modes/classic-survival.js ---- */
/* How Smart Are You? — Classic and Survival: choosing a mode and category, a run, the timers, answering, results and the once-only payout (finishRun).
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
/* a finished run pays out exactly once (G.res is the receipt). Personal bests compare runs of the same mode. */
function finishRun(cleared){if(G.res)return G.res;if(cleared)G.score+=500;const L=G.log,before=lvlInfo(S.prog.xp),w0=[S.wallet.coins,S.wallet.gems],mode=G.mode||'classic';
 if(!L.length)return G.res={xp:0,co:0,before,after:before,ms:[],pb:false,empty:true,bonus:[0,0],lv:[0,0,0],w0};
 let sv=0,svPts=0;if(mode==='survival'){sv=Math.max(0,Math.round((G.endAt||performance.now())-G.survStart));svPts=G.correct?Math.floor(sv/1000)*10:0;G.score+=svPts}
 const cats={},tr={};let rt=0,f=0;
 for(const e of L){const c=cats[e.cat]=cats[e.cat]||[0,0],t=tr[e.tier]=tr[e.tier]||[0,0];c[0]++;t[0]++;rt+=e.ms;if(e.ok){c[1]++;t[1]++;if(!f||e.ms<f)f=e.ms}}
 let xp=G.correct?Math.min(800,G.xp+25):0,co=G.correct?Math.min(200,G.correct*3+Math.floor(G.score/200)):0;
 const prev=S.history.filter(h=>h.mode===mode),was=Math.max(0,...prev.map(h=>h.s)),pb=G.score>was&&G.score>0,svpb=mode==='survival'&&prev.length>0&&sv>Math.max(0,...prev.map(h=>h.sv));
 /* bonuses outside the cap: long streaks, and beating an existing personal best */
 const sb=G.correct?Math.min(20,Math.max(0,G.bestStreak-4)*2):0,pbb=pb&&was>0?25:0;co+=sb+pbb;
 markDay(mode==='survival'?2:1);S.history.push(cleanH({t:Date.now(),mode,cat:G.cat,s:G.score,k:G.correct,w:G.wrong,tier:G.best,st:G.bestStreak,xp,co,d:Math.round((Date.now()-G.runStart)/1000),rt:Math.round(rt),n:L.length,f:Math.round(f),sv,cats,tr}));
 if(S.history.length>1000)S.history.shift();
 S.prog.xp+=xp;S.wallet.coins+=co;const after=lvlInfo(S.prog.xp),ms=[];
 for(let l=before.l+1;l<=after.l;l++){const m=MILE[l];if(m&&!S.prog.claimed.includes(l)){S.prog.claimed.push(l);S.wallet.coins+=m[0];S.wallet.gems+=m[1];ms.push([l,m[0],m[1]])}}
 const lv=payLevels();
 {const h=S.history[S.history.length-1];addPlay(h.d);dcUpdate({kind:'run',h})}   /* v0.15 */
 persist();renderHome();return G.res={xp,co,before,after,ms,pb,svpb,sv,svPts,bonus:[sb,pbb],lv,w0}}
/* ===== GAME MODES ================================================================
   Classic (unchanged): 3 lives; every question has its own timer that starts at 20s and
   shrinks 8% per correct answer, but never below the time needed to read and type; the
   difficulty tier rises every 2 correct answers; wrong answers and timeouts cost a life.
   Survival: 1 life and ONE shared countdown for the whole run. It starts at 30s, never stops
   (between questions, on other tabs, minimised), and right answers add a little time back.
   One wrong answer or an empty clock ends the run.
   Only one run can exist at a time: every timer carries the run's token and does nothing
   once that run has ended or a new one has started.
   ================================================================================== */
const MODES={
 classic:{icon:'🧠',name:'Classic',tag:'The original',hue:265,
  desc:'Three lives and a timer on every question that gets shorter as you get answers right.',
  rules:['3 lives. A wrong answer or running out of time costs one.','Every question has its own timer: 20 seconds to start, 8% shorter after each right answer, but always long enough to type the answer.','The difficulty rises every 2 correct answers, through 6 tiers from Warm-up to Ultra niche.','Score: 100 × tier, +10 for every second left, +25 for each answer in your streak (up to +250).']},
 survival:{icon:'⏳',name:'Survival',tag:'One life · one clock',hue:4,
  desc:'One life and a single countdown for the whole run. Right answers buy back a few seconds. One mistake ends it.',
  rules:['1 life. A wrong answer ends the run immediately.','One countdown starts at 30 seconds and never stops: not between questions, not if you switch tabs.','A right answer adds time: +3s for your first 10, then +2.5s, +2s and finally +1.5s from 30 on. Answer within 3 seconds for a bonus +1s (+0.5s after 20). The clock holds 45 seconds at most.','The difficulty rises every 2 correct answers, so questions get harder as the bonus shrinks.','Score: 120 × tier, up to +100 for speed, +30 for each answer in your streak (up to +300), then +10 for every second you survived.']},
};
const SURV={start:30,max:45,fastMs:3000};
