/* ---------- results and rewards ---------- */
function cgStandings(v){const W=v.winners||[];return v.players.map((p,i)=>({...p,i,win:W.includes(i)})).sort((a,b)=>(b.win-a.win)||((a.out?a.outRound:1e9)<(b.out?b.outRound:1e9)?1:(a.out?a.outRound:1e9)>(b.out?b.outRound:1e9)?-1:0)||(b.lives-a.lives)||(b.ok-a.ok))}
/** Rewards for the player: none for a game with fewer than 2 good answers (unless won). */
function cgReward(g,mePlace,win,beaten,online){const me=g.players.find(p=>p.human||p.me),m=online?1.3:[.5,.7,1,1.3,1.6,2,2.5][g.diff],opp=g.players.length-1;
 if(!win&&me.ok<2)return{xp:0,co:0,none:true};
 const xp=Math.min(900,Math.round((15*me.ok+25*beaten+(win?60+30*opp:0))*m)),co=Math.min(300,Math.round((3*me.ok+6*beaten+(win?25+10*opp:0))*m));return{xp,co}}
function cgResults(){const g=CGS,v=cgVM(),st=cgStandings(v),meI=v.players.findIndex(p=>p.me),me=v.players[meI],win=(v.winners||[]).length===1&&v.winners[0]===meI,draw=(v.winners||[]).length>1,place=st.findIndex(p=>p.me)+1;
 if(!g.endSnd){g.endSnd=1;endSound(win)}
 const beaten=st.slice(place).length;                         /* everyone who finished below you */
 let rw={xp:0,co:0,none:true},x={ach:[],mis:[]},before=lvlInfo(S.prog.xp).l,w0=[S.wallet.coins,S.wallet.gems];
 if(!g.recorded){g.recorded=true;rw=cgRecord(g,v,{win,draw,place,beaten,meI});x=rw.extra||x}else rw=g.reward||rw;
 const W=(v.winners||[]).map(i=>v.players[i]);
 const head=win?'🏆 You win!':draw?(W.some(p=>p.me)?'🤝 Draw!':'🤝 It’s a draw'):W.length?`${esc2(W[0].name)} wins`:'Game over';
 const why=v.reason==='exhausted'?`<p class="mut">Every answer in this category was used, so the players with the most lives share the win.</p>`:v.reason==='left'?'<p class="mut">You left the game early.</p>':'';
 const C=cgCat(v.cat),rows=st.map((p,k)=>`<tr class="${p.me?'me':''}"><td>${p.win?'🏆':k+1}</td><td class="cgrn">${avatarHTML(p.av)} ${esc2(p.name)}${p.me?' (you)':''}${p.bot?`<small>${CG_DIFF[p.diff].n}${S.cg.ai[p.name]?` · has won ${S.cg.ai[p.name].w} of ${S.cg.ai[p.name].p} games with you`:''}</small>`:''}</td><td>${p.ok}</td><td>${p.lost}</td><td>${p.out?'Round '+p.outRound:p.win?'Winner':'—'}</td></tr>`).join('');
 const gc=S.wallet.coins-w0[0];
 $('#gb').innerHTML=`<h2>${head}</h2>${why}<p class="mut">${C.icon} ${esc2(C.name)} · ${esc2(v.sub)} · ${v.players.length-1} opponent${v.players.length>2?'s':''} · ${v.round} round${v.round>1?'s':''}</p>
 <div class="tw"><table class="t cgres"><tr><th>#</th><th>Player</th><th>Answers</th><th>Lives lost</th><th>Out</th></tr>${rows}</table></div>
 <div class="mgrid">${M(place+' of '+v.players.length,'Your place')}${M(me.ok,'Good answers')}${M(beaten,'Opponents beaten')}${M('+'+(rw.xp||0),'XP')}${M('+'+fmt(Math.max(0,gc)),'Coins')}</div>
 ${rw.none?'<p class="mut">Give at least 2 good answers (or win) to earn XP and coins.</p>':''}
 ${x.ach.map(t=>`<p>🏅 Achievement unlocked: <b>${t}</b></p>`).join('')}${x.mis.map(t=>`<p>🎯 Mission complete: <b>${t}</b> (claim it in Missions)</p>`).join('')}
 <div class="qbtns">${g.net?`<button class="x" data-cg="online">Back to online</button>`:`<button class="x" data-cgagain>Play again</button><button class="x" data-cg="ai">Change setup</button>`}<button class="x" data-cg="home">Category Game</button><button class="x" data-a="close">Menu</button></div>`;
 if(win){const h=$('#gb h2');if(h){const r=h.getBoundingClientRect();setTimeout(()=>fxReward(r.left+r.width/2,r.top+20),200)}}
 const a=lvlInfo(S.prog.xp).l;if(a>before)setTimeout(()=>levelUp(a),700)}
/** Saves the finished game to the player's Category Game stats, once. */
function cgRecord(g,v,o){const c=S.cg,me=v.players[o.meI],net=!!g.net;
 if(net){if(c.online.seen.includes(g.code))return{xp:0,co:0,none:true};c.online.seen.push(g.code);c.online.seen=c.online.seen.slice(-40)}
 const played=me.ok>0||me.lost>0;                               /* a game you took part in */
 if(!played)return{xp:0,co:0,none:true};
 const opp=v.players.length-1;
 c.games++;if(o.win)c.wins++;else if(o.draw&&(v.winners||[]).includes(o.meI))c.draws++;else c.losses++;
 c.answers+=me.ok;c.livesLost+=me.lost;c.bestRounds=Math.max(c.bestRounds,me.out?me.outRound-1:v.round);   /* full rounds you survived */
 if(!net){c.maxBeaten=Math.max(c.maxBeaten,o.beaten);c.ko+=v.players.filter(p=>p.bot&&p.out&&!p.left).length;
  if(o.win){c.bestDiff=Math.max(c.bestDiff,g.diff);c.maxWinOpp=Math.max(c.maxWinOpp,opp);if(me.lost===0&&opp>=3)c.perfect++;c.catWins[v.cat]=(c.catWins[v.cat]||0)+1}
  for(const p of v.players)if(p.bot){const a=c.ai[p.name]=c.ai[p.name]||{p:0,w:0};a.p++;if((v.winners||[]).length===1&&v.players[v.winners[0]]===p)a.w++}}
 else{c.online.games++;if(o.win)c.online.wins++}
 if(!net){const X=c.x;if(g.diff>=3){if(o.win){X.streak++;X.bestStreak=Math.max(X.bestStreak,X.streak)}else X.streak=0}
  if(o.win){if(g.diff>=5)X.elite++;if(g.diff>=4&&opp>=5)X.koHard=1;if(g.diff>=6&&me.lost===0)X.god=1;if(opp>=8){X.wins8++;if(me.lost===0)X.perf8=1}}}
 markDay(net?16:4);
 c.recent.push({t:Date.now(),cat:v.cat,n:opp,d:net?-1:g.diff,place:o.place,win:o.win?1:0,ok:me.ok,r:v.round});c.recent=c.recent.slice(-20);
 const rw=cgReward(net?{players:v.players.map(p=>({...p,human:p.me}))}:g,o.place,o.win,o.beaten,net);
 if(!rw.none)grant(rw.xp,rw.co,0);
 /* missions */
 const ex={ach:[],mis:[]};rollMissions();
 for(const sc in S.missions)for(const m of S.missions[sc].list){const P=MPOOL[sc][m.i],was=m.p>=P[1];
  if(P[0]==='cgplay')m.p++;else if(P[0]==='cgans')m.p+=me.ok;else if(P[0]==='cgwin'&&o.win)m.p++;else if(P[0]==='cgbeat'&&!net)m.p+=v.players.filter(p=>p.bot&&p.out).length;
  if(!was&&m.p>=P[1])ex.mis.push(P[2])}
 if(!net&&g.t0)addPlay((Date.now()-g.t0)/1000);dcUpdate({kind:'cg',net,win:!!o.win,diff:g.diff,opp,lost:me.lost});   /* v0.15 */
 ex.ach=checkAch();persist();renderHome();rw.extra=ex;g.reward=rw;return rw}

