function cgClosed(){if(!CGS)return;if(CGS.net){const c=NET.code;cgNetStop();CGS.over=true;if(c)netCall('cg_leave_room',{p_code:c}).catch(()=>{})}else if(!CGS.over&&!G.active)cgStop()}
