async function cgNetRefresh(){if(!NET.code)return;try{cgNetShow(await netCall('cg_get_room',{p_code:NET.code}))}catch(e){if(String(e.message).includes('not_in_room')){cgNetStop();cgOnlineHome('You are no longer in that room.')}}}
