/* ----- the Achievements page ----- */
let achF='all';
VIEW.achievements=()=>{const v=achVals(),un=ACH.filter(a=>S.ach[a.id]),pts=un.reduce((s,a)=>s+a.tier*10,0),max=ACH.reduce((s,a)=>s+a.tier*10,0);
 const F=[['all','All'],['got','Unlocked'],['todo','Locked'],['secret','🤫 Secret']].concat(Object.entries(ACH_G));
 const show=ACH.filter(a=>achF==='all'||(achF==='got'&&S.ach[a.id])||(achF==='todo'&&!S.ach[a.id])||(achF==='secret'&&a.h)||a.g===achF)
  .sort((x,y)=>(!!S.ach[y.id]-!!S.ach[x.id])||(achF==='todo'?(v[y.k]/y.t)-(v[x.k]/x.t):0));
 const legend=ACH_T.slice(1).map(([n,c],i)=>`<span class="tierb2" style="--tc:${c}">${n}</span>`).join('');
 return`<h2>Achievements</h2><div class="achsum"><div><b>${un.length} / ${ACH.length}</b><small>unlocked</small></div><div><b>${pts} / ${max}</b><small>achievement points</small></div><div><b>${ACH.filter(a=>a.tier>=5&&S.ach[a.id]).length}</b><small>Prestige</small></div></div>
 <span class="bar thick"><i style="width:${un.length/ACH.length*100}%"></i></span>
 <p class="mut" style="margin-top:8px">Rewards are paid once, the moment you unlock an achievement. Difficulty: ${legend}. Some rewards are cosmetics you can’t buy.</p>
 <div class="mfil" role="group" aria-label="Filter achievements">${F.map(([k,n])=>`<button class="chip" data-af="${k}" aria-pressed="${achF===k}">${n}</button>`).join('')}</div>
 <div class="agrid">${show.map(a=>achCard(a,v)).join('')||'<p class="mut">Nothing here yet.</p>'}</div>`};
function achCard(a,v){const got=S.ach[a.id],T=ACH_T[a.tier],p=Math.min(a.t,v[a.k]||0),items=ITEMS.filter(i=>i.req&&i.req.ach===a.id);
 if(a.h&&!got)return`<div class="ac sec" style="--tc:${T[1]}"><span class="ai">❔</span><span class="tierb2" style="--tc:${T[1]}">${T[0]} · Secret</span><b>Secret achievement</b><small>${esc2(a.hint||'Keep playing to discover it.')}</small><small>Reward: hidden until you find it</small></div>`;
 const rew=rw(a.r)+(items.length?`<br>🎁 Exclusive: ${items.map(i=>esc2(i.name)+' ('+SLOTS[i.slot].toLowerCase()+')').join(', ')}`:'');
 return`<div class="ac ${got?'got':''} t${a.tier}" style="--tc:${T[1]}"><span class="ai">${a.i}</span><span class="tierb2" style="--tc:${T[1]}">${T[0]}${a.h?' · Secret':''}</span><b>${esc2(a.n)}</b><small>${esc2(a.d)}</small>
 ${got?`<small class="acdone">✓ Unlocked ${new Date(got.t).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}</small>`:`<span class="bar"><i style="width:${p/a.t*100}%"></i></span><small>${fmt(p)} / ${fmt(a.t)}</small>`}<small>Reward: ${rew}</small></div>`}
/** Your rarest unlocked achievements, for the profile. */
function achShowcase(){const L=ACH.filter(a=>S.ach[a.id]).sort((x,y)=>y.tier-x.tier||y.r[0]-x.r[0]).slice(0,3);
 return L.length?`<div class="showc">${L.map(a=>{const T=ACH_T[a.tier];return`<div class="ac got t${a.tier}" style="--tc:${T[1]}"><span class="ai">${a.i}</span><span class="tierb2" style="--tc:${T[1]}">${T[0]}</span><b>${esc2(a.n)}</b><small>${esc2(a.d)}</small></div>`}).join('')}</div>`:'<p class="mut">Unlock achievements to show off your rarest ones here.</p>'}

