function bgReset(){if(!W)return;if(!ca)colors();const n=look('bg');BGcur=(BGR[n]||BGR.particles)(ctx,W,H);bgDirty=true}
addEventListener('resize',size);
addEventListener('pointermove',e=>{mp={x:e.clientX,y:e.clientY};if(!cfg.calm){tx=(e.clientX/innerWidth-.5)*2;ty=(e.clientY/innerHeight-.5)*2}});
addEventListener('pointerleave',()=>{tx=ty=0;mp={x:-999,y:-999}});
