document.addEventListener('pointerover',e=>{const b=e.target.closest&&e.target.closest('#sbody .invrow [data-eq]');if(b&&ITEM[b.dataset.eq])invShow(ITEM[b.dataset.eq].slot,b.dataset.eq)});
