/* How Smart Are You? — The player record on the profile.
   Plain script (not a module): it shares one global scope with the other files, loaded in the
   order listed in index.html. */
/* ---------- the player record on the profile ---------- */
const durL=s=>{s=Math.round(s);const h=Math.floor(s/3600),m=Math.floor(s%3600/60);return h?`${fmt(h)}h ${m}m`:m?`${m}m`:`${s}s`};
const pctS=x=>Number.isFinite(x)&&x>0?Math.round(x)+'%':'–';
function profileRecord(){const L=lifeStats(),li=lvlInfo(S.prog.xp),un=ACH.filter(a=>S.ach[a.id]),pts=un.reduce((s,a)=>s+a.tier*10,0),tiers=[1,2,3,4,5].map(t=>un.filter(a=>a.tier===t).length);
 const days=new Set(S.days);for(const h of S.history)days.add(dayKey(new Date(h.t)));
 const form=L.recentN>=3&&L.qsQ>=30?(()=>{const d=Math.round(L.recentAcc-L.qsAcc);return`<p class="mut prform">Recent form: ${pctS(L.recentAcc)} accuracy over your last ${L.recentN} Classic and Survival runs, ${d>0?`<b class="up">▲ ${d} points above</b>`:d<0?`<b class="down">▼ ${-d} points below</b>`:'level with'} your lifetime ${pctS(L.qsAcc)}.</p>`})():'';
 const row=(i,n,a,b,c,d)=>`<tr><td>${i} ${n}</td><td data-l="Played">${a}</td><td data-l="Record">${b}</td><td data-l="Accuracy">${c}</td><td data-l="Best">${d}</td></tr>`;
 return`<h3>📜 Player record</h3><p class="mut" style="margin-top:-4px">Playing since ${new Date(S.created).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})} · ${days.size} day${days.size===1?'':'s'} played</p>
 <div class="mgrid prgrid">${M(fmt(S.prog.xp),'Total XP')}${M(fmt(L.games),'Games played (all modes)')}${M(fmt(L.correct),'Correct answers (all modes)')}${M(pctS(L.acc),'Overall accuracy')}${M(L.bestStreak||'–','Best answer streak')}${M(L.tier?TN[L.tier-1]:'–','Highest tier')}${M(durL(L.playS),'Time played')}${M('🪙 '+fmt(L.coinsEarned),'Brain Coins earned')}${M(un.length+' / '+ACH.length,'Achievements')}${M(fmt(pts),'Achievement points')}${M(S.daily.best||'–','Best Daily Challenge streak')}</div>
 ${form}
 <div class="tw"><table class="t prmodes"><tr><th>Mode</th><th>Played</th><th>Record</th><th>Accuracy</th><th>Best</th></tr>
 ${row('🧠','Classic',fmt(L.classic.games),L.classic.k?fmt(L.classic.k)+' correct':'–',pctS(L.classic.q?L.classic.k/L.classic.q*100:0),L.classic.games?fmt(L.classic.best)+' pts':'–')}
 ${row('⏳','Survival',fmt(L.survival.games),L.survival.k?fmt(L.survival.k)+' correct':'–',pctS(L.survival.q?L.survival.k/L.survival.q*100:0),L.survival.games?fmtT(L.survival.sv)+' · '+fmt(L.survival.best)+' pts':'–')}
 ${row('🤖','Human vs AI',fmt(L.hva.g),L.hva.g?`${fmt(L.hva.w)} W · ${fmt(L.hva.l)} L${L.hva.d?' · '+fmt(L.hva.d)+' D':''} (${pctS(L.hva.rate)})`:'–','–',L.hva.streak?L.hva.streak+' Hard+ wins in a row':'–')}
 ${row('🧩','Riddle Mode',fmt(L.riddle.runs),L.riddle.runs?fmt(L.riddle.solved)+' solved':'–',pctS(L.riddle.acc),L.riddle.runs?L.riddle.best+' in one run':'–')}
 ${L.online.g?row('🌐','Online',fmt(L.online.g),fmt(L.online.w)+' wins','–','–'):''}</table></div>
 <p class="mut prnote">Accuracy counts typed answers in Classic, Survival and Riddle Mode (the Category Game has no wrong answers to count). Time played adds up finished Classic, Survival and Riddle runs; Human vs AI time is counted from version 0.15. Coins earned = coins you have plus coins spent. Tiers unlocked: ${tiers.map((n,i)=>`<span style="color:${ACH_T[i+1][1]}">${ACH_T[i+1][0]} ${n}</span>`).join(' · ')}.</p>`}
;
